import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.z3u3TMv0.js";const m=JSON.parse('{"title":"이용약관","description":"MiniTavern Ultra 이용약관.","frontmatter":{"title":"이용약관","description":"MiniTavern Ultra 이용약관.","head":[["meta",{"property":"og:title","content":"이용약관 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra 이용약관."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/terms"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/terms"}]]},"headers":[],"relativePath":"ko/terms.md","filePath":"ko/terms.md","lastUpdated":1786329590000}'),o={name:"ko/terms.md"};function n(l,a,s,h,d,p){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="이용약관" tabindex="-1">이용약관 <a class="header-anchor" href="#이용약관" aria-label="Permalink to &quot;이용약관&quot;">​</a></h1><p><strong>MiniTavern Ultra（이하 「본 앱」）에 오신 것을 환영합니다. 이용 전 본 약관을 읽어 주세요. 다운로드·설치·이용은 동의로 간주됩니다. 동의하지 않으면 즉시 이용을 중단하세요.</strong></p><h2 id="_1-수락과-변경" tabindex="-1">1. 수락과 변경 <a class="header-anchor" href="#_1-수락과-변경" aria-label="Permalink to &quot;1. 수락과 변경&quot;">​</a></h2><p>본 앱 이용은 약관 동의를 의미합니다. 앱 내 공지 또는 문서로 갱신할 수 있으며, 이후에도 이용하면 변경에 동의한 것으로 봅니다.</p><h2 id="_2-서비스-범위" tabindex="-1">2. 서비스 범위 <a class="header-anchor" href="#_2-서비스-범위" aria-label="Permalink to &quot;2. 서비스 범위&quot;">​</a></h2><p>AI 대화/롤플레이, 캐릭터 카드 생성·가져오기, 제3자 또는 로컬 모델 API에 대한 BYOK, 월드북/정규식/페르소나, 기기 내 저장 및 백업 내보내기를 제공합니다. 자체 모델 연산 구독은 판매하지 않습니다.</p><h2 id="_3-이용자-책임" tabindex="-1">3. 이용자 책임 <a class="header-anchor" href="#_3-이용자-책임" aria-label="Permalink to &quot;3. 이용자 책임&quot;">​</a></h2><p>법령을 준수하여 이용하세요. 프롬프트, 가져온 카드, 생성물 공유에 대한 책임은 이용자에게 있습니다. API 키 유출·요금 위험은 이용자 부담이며 제공자 정책을 따라야 합니다.</p><h2 id="_4-면책" tabindex="-1">4. 면책 <a class="header-anchor" href="#_4-면책" aria-label="Permalink to &quot;4. 면책&quot;">​</a></h2><p>본 앱은 「있는 그대로」 제공됩니다. 무중단·무오류, AI 출력의 정확성·합법성을 보장하지 않습니다. 법이 허용하는 범위에서 간접 손해, 제3자 장애, 백업 미실시로 인한 데이터 손실 등에 대해 책임지지 않습니다.</p><h2 id="문의" tabindex="-1">문의 <a class="header-anchor" href="#문의" aria-label="Permalink to &quot;문의&quot;">​</a></h2><p><strong>이메일:</strong> <a href="mailto:minitavern@gmail.com" target="_blank" rel="noreferrer">minitavern@gmail.com</a> — 최종 업데이트: 2026-08-10</p><p>관련: <a href="/ultra_guides/ko/privacy">개인정보</a> · <a href="/ultra_guides/manual/">매뉴얼（简体中文）</a></p>',13)])])}const _=e(o,[["render",n]]);export{m as __pageData,_ as default};
